-- ============================================================================
-- Tesla WIP Inventory Reconciliation - Database Schema
-- Virtual Inventory Reconciliation & Disposition System
-- All data is synthetic, generated by reconcile.py --build
-- ============================================================================

-- MES (Manufacturing Execution System) virtual inventory: what the system
-- believes is on hand at each location.
CREATE TABLE IF NOT EXISTS mes_inventory (
    record_id           INTEGER PRIMARY KEY,
    part_number         TEXT    NOT NULL,
    description         TEXT    NOT NULL,
    category            TEXT    NOT NULL,
    location            TEXT    NOT NULL,
    mes_qty             INTEGER NOT NULL,
    unit_cost           REAL    NOT NULL,
    annual_usage_qty    INTEGER NOT NULL,
    last_movement_date  TEXT    NOT NULL
);

-- Physical cycle-count results: what was actually counted on the floor.
CREATE TABLE IF NOT EXISTS physical_counts (
    record_id   INTEGER PRIMARY KEY,
    part_number TEXT    NOT NULL,
    location    TEXT    NOT NULL,
    physical_qty INTEGER NOT NULL,
    counted_by  TEXT    NOT NULL,
    count_date  TEXT    NOT NULL,
    FOREIGN KEY (record_id) REFERENCES mes_inventory (record_id)
);

-- Discrepancies found by matching MES virtual qty against physical counts.
-- variance_qty is signed (physical - MES); variance_value is signed dollars.
CREATE TABLE IF NOT EXISTS discrepancies (
    discrepancy_id  INTEGER PRIMARY KEY,
    record_id       INTEGER NOT NULL,
    part_number     TEXT    NOT NULL,
    location        TEXT    NOT NULL,
    mes_qty         INTEGER NOT NULL,
    physical_qty    INTEGER NOT NULL,
    variance_qty    INTEGER NOT NULL,
    variance_type   TEXT    NOT NULL,   -- SHORT | OVER | UNACCOUNTED
    variance_value  REAL    NOT NULL,
    aging_days      INTEGER NOT NULL,
    aging_bucket    TEXT    NOT NULL,   -- 0-7 | 8-30 | 31-90 | 90+
    detected_date   TEXT    NOT NULL,
    FOREIGN KEY (record_id) REFERENCES mes_inventory (record_id)
);

-- Disposition workflow: every discrepancy is driven to closure by an owner
-- with a due date and a status.
CREATE TABLE IF NOT EXISTS dispositions (
    disposition_id  INTEGER PRIMARY KEY,
    discrepancy_id  INTEGER NOT NULL,
    disposition     TEXT    NOT NULL,   -- SCRAP | REWORK | RETURN-TO-STOCK | QUARANTINE | WRITE-OFF
    owner           TEXT    NOT NULL,
    due_date        TEXT    NOT NULL,
    status          TEXT    NOT NULL,   -- OPEN | IN-PROGRESS | CLOSED
    notes           TEXT,
    FOREIGN KEY (discrepancy_id) REFERENCES discrepancies (discrepancy_id)
);

-- ABC classification by annual usage value (A = top 80% of value,
-- B = next 15%, C = remainder).
CREATE TABLE IF NOT EXISTS abc_classification (
    part_number         TEXT PRIMARY KEY,
    annual_usage_value  REAL NOT NULL,
    abc_class           TEXT NOT NULL    -- A | B | C
);

CREATE INDEX IF NOT EXISTS idx_disc_location   ON discrepancies (location);
CREATE INDEX IF NOT EXISTS idx_disc_type       ON discrepancies (variance_type);
CREATE INDEX IF NOT EXISTS idx_disc_bucket     ON discrepancies (aging_bucket);
CREATE INDEX IF NOT EXISTS idx_disp_status     ON dispositions (status);
CREATE INDEX IF NOT EXISTS idx_disp_due        ON dispositions (due_date);
CREATE INDEX IF NOT EXISTS idx_mes_location    ON mes_inventory (location);
